<script lang="ts">
 import {Api} from './api';
 import type {PublicMemberProfile,Template} from './types';
 let {handle,onback,onpreview}:{handle:string;onback:()=>void;onpreview:(t:Template)=>void}=$props();
 let profile=$state<PublicMemberProfile|null>(null);let busy=$state(false);let error=$state('');let generation=0;
 async function load(value=handle){const current=++generation;profile=null;error='';busy=true;try{const p=await new Api().publicProfile(value);if(current===generation)profile=p;}catch(e){if(current===generation)error=e instanceof Error?e.message:'This profile is not available.';}finally{if(current===generation)busy=false;}}
 $effect(()=>{void load(handle);return()=>{generation++;};});
</script>
<main class="library-page profile-page"><button class="text-button" onclick={onback}>← Leaderboard</button>
 {#if busy}<p role="status">Loading public profile…</p>{:else if error}<section class="profile-error" role="alert"><h1>Profile unavailable.</h1><p>{error}</p><button class="secondary" onclick={()=>load()}>Retry profile</button></section>
 {:else if profile}<header class="public-member"><div class="public-avatar" aria-hidden="true">{profile.handle.slice(0,2).toUpperCase()}</div><div><span class="eyebrow">PUBLIC CONTRIBUTOR</span><h1>@{profile.handle}</h1><p>Useful structures, shared with the community.</p></div></header><dl class="public-stats"><div><dt>Contribution points</dt><dd>{profile.total_points}</dd></div><div><dt>Approved templates</dt><dd>{profile.approved_contributions}</dd></div><div><dt>Public rank</dt><dd>{profile.rank?'#'+profile.rank:'Not ranked'}</dd></div></dl>
 <div class="profile-section-heading"><h2>Published templates</h2><p>Copy a structure into your own private space and make it yours.</p></div><div class="profile-templates">{#each profile.templates as t (t.id)}<article><span class="pill">{t.form.family==='deck'?'Slides':t.form.family==='sheet'?'Spreadsheet':'Document'} · {t.form.locale}</span><h3>{t.title}</h3><p>{t.summary}</p><ol>{#each t.sections.slice(0,3) as s}<li>{s}</li>{/each}</ol><small>{t.author} · {t.license} · v{t.version}</small><button class="text-button" onclick={()=>onpreview(t)} aria-label={'Preview '+t.title}>Preview template ↗</button></article>{:else}<p class="empty-profile">No published templates yet. Approved contributions will appear here.</p>{/each}</div>
 {/if}
</main>
<style>
 .public-member{display:flex;align-items:center;gap:24px;margin:32px 0}.public-avatar{flex:none;display:grid;place-items:center;width:88px;height:88px;background:#e3ebd5;border-radius:24px;font-size:25px;color:#4f6b40}.public-member h1{font-size:36px;margin:10px 0;letter-spacing:-1.2px;overflow-wrap:anywhere}.public-member p,.profile-section-heading p{font-size:13px;color:#7c886e;line-height:1.8}.public-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;padding:26px;background:#f0f4e9;border:1px solid #dce3d1;border-radius:14px}.public-stats>div{border-left:1px solid #d9e0cd;padding-left:22px;min-width:0}.public-stats>div:first-child{border:0;padding:0}.public-stats dt{font-size:11px;color:#7b886c}.public-stats dd{font-size:29px;margin:12px 0 0}.profile-section-heading{margin:36px 0 22px}.profile-section-heading h2{font-size:23px;letter-spacing:-.5px}.profile-templates{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.profile-templates article{background:#fff;border:1px solid #e0e5d5;border-radius:12px;padding:24px;display:flex;flex-direction:column;min-width:0}.profile-templates h3{font-size:20px;line-height:1.5;margin:19px 0 8px;overflow-wrap:anywhere}.profile-templates p,.profile-templates ol{font-size:12px;color:#7b886f;line-height:1.8}.profile-templates ol{padding-left:17px}.profile-templates small{margin-top:auto;font-size:10px;color:#849074;padding-top:17px;border-top:1px solid #edf0e5}.profile-templates button{margin-top:13px;text-align:left}.empty-profile{font-size:13px;color:#7c886e}.profile-error{padding:30px;background:#fff;border:1px solid #e0e5d5;border-radius:12px;margin-top:24px}.profile-error h1{font-size:28px}.profile-error p{font-size:13px;line-height:1.8;color:#7b886e}@media(max-width:1000px){.profile-templates{grid-template-columns:1fr 1fr}}@media(max-width:650px){.public-member{align-items:flex-start;gap:15px}.public-avatar{width:58px;height:58px;border-radius:15px;font-size:17px}.public-member h1{font-size:26px}.public-member p{font-size:11px}.public-stats{padding:20px;gap:10px}.public-stats>div{padding-left:10px}.public-stats dd{font-size:22px}.public-stats dt{font-size:10px}.profile-templates{grid-template-columns:1fr}}
</style>
